// drop-in replacement for the mocking library
function createMock(returnValue) {
  const calls = [];
  const fn = (...args) => {
    calls.push(args);
    return returnValue;
  };
  fn.calls = calls;
  fn.calledWith = (...expected) =>
    calls.some(args => args.length === expected.length
      && args.every((a, i) => a == expected[i]));
  fn.calledOnce = () => calls.length > 0;
  return fn;
}
